class Solution { private lateinit var words:Array<String>;private lateinit var score:IntArray;private lateinit var available:IntArray;fun maxScoreWords(words:Array<String>,letters:CharArray,score:IntArray):Int{this.words=words;this.score=score;available=IntArray(26);for(ch in letters)available[ch-'a']++;return dfs(0)};private fun dfs(index:Int):Int{if(index==words.size)return 0;var best=dfs(index+1);val need=IntArray(26);var wordScore=0;var valid=true;for(ch in words[index]){val letter=ch-'a';wordScore+=score[letter];if(++need[letter]>available[letter])valid=false};if(valid){for(i in 0..25)available[i]-=need[i];best=maxOf(best,wordScore+dfs(index+1));for(i in 0..25)available[i]+=need[i]};return best} }
